package com.ruoyi.medical.persistence;
import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.*;
/** Explicit SourceVerifier lane. Production dependencies must be installed; no provider fallback. */
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(name="medical.professional-runtime.source-verifier-enabled",havingValue="true",matchIfMissing=false)
public class TaskSourceVerifierInvocationConfiguration {
 @Bean(name="sourceVerifierInvocationHttpSchema") TaskInvocationHttpSchema sourceVerifierInvocationHttpSchema(FormalInvocationSchema schema)throws Exception{return new TaskInvocationHttpSchema(schema);}
 @Bean TaskSourceVerifierInvocationSchema taskSourceVerifierInvocationSchema()throws Exception{return new TaskSourceVerifierInvocationSchema();}
 @Bean TaskSourceVerifierInvocationObjects taskSourceVerifierInvocationObjects(DataSource data,PermissionSchema json,FormalInvocationSchema schema,TaskSourceVerifierInvocationSchema exact,DependencyManifestSchema manifests){return new TaskSourceVerifierInvocationObjects(data,json,schema,exact,manifests);}
 @Bean TaskSourceVerifierInvocationRecords taskSourceVerifierInvocationRecords(DataSource data,TaskSourceVerifierInvocationObjects objects,FormalInvocationSchema schema,PermissionSchema json,TaskSourceVerifierProducerAuthority producers){return new TaskSourceVerifierInvocationRecords(data,objects,schema,json,producers);}
 @Bean TaskSourceVerifierInvocationContext taskSourceVerifierInvocationContext(DataSource data,ModelConfigurationService models,ModelEligibilityAuthority eligibility,ResourceReadAuthority resources,SourceReadAuthority sources,TaskInvocationPackages packages,FormalInvocationSourceOriginals originals,FormalInvocationSchema schema,TaskSourceVerifierInvocationSchema exact,PermissionSchema json,@Qualifier("formalInvocationObjectTransport")RuntimeObjectTransport transport,TaskSourceVerifierProducerAuthority producers,TaskSourceVerifierContextReads contentReads){return new TaskSourceVerifierInvocationContext(data,models,eligibility,resources,sources,packages,originals,schema,exact,json,transport,producers,contentReads);}
 @Bean TaskSourceVerifierInvocationService taskSourceVerifierInvocationService(DataSource data,TaskSourceVerifierSupervisor supervisors,TaskSourceVerifierWorkerAccess workers,RunTokenAuthority tokens,TaskSourceVerifierInvocationContext contexts,TaskSourceVerifierInvocationRecords records,FormalInvocationReservations reservations,FormalInvocationDispatch dispatch,FormalInvocationReceiptObjects receipts,FormalInvocationSettlement settlement,FormalInvocationObjectRegistration objects,FormalProviderCaptureEvidence captures,FormalInvocationSchema schema)throws Exception{return new TaskSourceVerifierInvocationService(data,supervisors,workers,tokens,contexts,records,reservations,dispatch,receipts,settlement,objects,new TaskInvocationResults(data,null,settlement,objects,captures,schema),schema);}
 @Bean TaskSourceVerifierInvocationContextOrchestrator taskSourceVerifierInvocationContextOrchestrator(TaskSourceVerifierHostAccess hosts,TaskSourceVerifierSupervisor supervisors,TaskSourceVerifierInvocationContext contexts,FormalInvocationSourceOriginals originals,TaskInvocationPackages packages,FormalTokenizerRunner tokenizer,TaskSourceVerifierInvocationObjects objects,@Qualifier("formalInvocationObjectTransport")RuntimeObjectTransport transport,TaskSourceVerifierInvocationRecords records,TaskSourceVerifierInvocationService invocations){return new TaskSourceVerifierInvocationContextOrchestrator(hosts,supervisors,contexts,originals,packages,tokenizer,objects,transport,records,invocations);}
 @Bean(name="sourceVerifierInvocationLocalBridge") TaskInvocationLocalBridge sourceVerifierInvocationLocalBridge(org.springframework.core.env.Environment e){String p="medical.professional-runtime.source-verifier-gateway.";return new TaskInvocationLocalBridge(new TaskInvocationLocalBridge.Configuration(java.nio.file.Path.of(e.getRequiredProperty(p+"executable")),e.getRequiredProperty(p+"executable-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"entrypoint")),e.getRequiredProperty(p+"entrypoint-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"package-root")),java.nio.file.Path.of(e.getRequiredProperty(p+"package-manifest")),e.getRequiredProperty(p+"package-manifest-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"private-configuration")),java.time.Duration.ofSeconds(Long.parseLong(e.getRequiredProperty(p+"timeout-seconds")))));}
 @Bean TaskSourceVerifierInvocationBridge taskSourceVerifierInvocationBridge(TaskSourceVerifierInvocationContextOrchestrator contexts,TaskSourceVerifierInvocationService service,@Qualifier("sourceVerifierInvocationLocalBridge")TaskInvocationLocalBridge bridge,org.springframework.core.env.Environment e)throws Exception{return new TaskSourceVerifierInvocationBridge(contexts,service,bridge,java.time.Duration.ofSeconds(Long.parseLong(e.getRequiredProperty("medical.professional-runtime.source-verifier-model-token-lifetime-seconds"))));}
}
